+func (cache *DiskBlockCacheStandard) syncBlockCountsFromDb() error {
+	// We take a write lock for this to prevent any reads from happening while
+	// we're syncing the block counts.
+	cache.lock.Lock()
+	defer cache.lock.Unlock()
