public class MainActivity extends AuthenticatedActivity implements FragmentManager.OnBackStackChangedListener {

    public ContributionsActivityPagerAdapter contributionsActivityPagerAdapter;
    public boolean isContributionsFragmentVisible = true;

    @Override
    public void onBackPressed() {
        DrawerLayout drawer = (DrawerLayout) findViewById(R.id.drawer_layout);
        String contributionsFragmentTag =
                contributionsActivityPagerAdapter.makeFragmentName(R.id.pager, 0);
        String nearbyFragmentTag =
                contributionsActivityPagerAdapter.makeFragmentName(R.id.pager, 1);

        if (drawer.isDrawerOpen(GravityCompat.START)) {
            drawer.closeDrawer(GravityCompat.START);
        } else if (getSupportFragmentManager().findFragmentByTag(contributionsFragmentTag) != null
                && isContributionsFragmentVisible) {
            ContributionsFragment contributionsFragment =
                    (ContributionsFragment) getSupportFragmentManager()
                            .findFragmentByTag(contributionsFragmentTag);

            if (contributionsFragment.getChildFragmentManager()
                    .findFragmentByTag(ContributionsFragment.MEDIA_DETAIL_PAGER_FRAGMENT_TAG) != null) {
                contributionsFragment.getChildFragmentManager().popBackStack();
                showTabs();
            } else {
                finish();
            }
        } else if (getSupportFragmentManager().findFragmentByTag(nearbyFragmentTag) != null
                && !isContributionsFragmentVisible) {
            NearbyParentFragmentPresenter.getInstance().backButtonClicked();
        } else {
            super.onBackPressed();
        }
    }
}
