          <div className={styles.contentDaedalus}>
            {intl.formatMessage(messages.aboutContentDaedalusMembers)}
          </div>
          <h2>{apiHeadline}</h2>
          <div className={styles.apiMembers}>
            {apiMembers}
          </div>
        </div>
      </div>
    );
  }
}
