  return keys.sort(function(buf1, buf2) {
    var len = buf1.length > buf1.length ? buf1.length : buf2.length;
    for (var i = 0; i <= len; i++) {
      if (buf1[i] === undefined)
        return -1;
      if (buf2[i] === undefined)
        return 1;
      if (buf1[i] < buf2[i])
