	typeOfBinarySet = reflect.TypeOf([][]byte{})
)

func (d decoder) AsSpecial(v reflect.Value) (bool, interface{}, error) {
	unsupportedFmt := "unsupported type: %v, the docstore driver for DynamoDB does not decode set types"
