func (r *Repository) LoadBlob(t pack.BlobType, id backend.ID, buf []byte) ([]byte, error) {
	packID, tpe, offset, length, err := r.idx.Lookup(id)
	if err != nil {
		return nil, err
	}

	if length > uint(cap(buf))+crypto.Extension {
		return nil, errors.New("buf is too small")
	}

	if tpe != t {
		return nil, fmt.Errorf("blob has wrong type %v (wanted: %v)", tpe, t)
	}

	rd, err := r.be.GetReader(backend.Data, packID.String(), offset, length)
	if err != nil {
		return nil, err
	}

	ciphertextBuf := make([]byte, length)
	_, err = io.ReadFull(rd, ciphertextBuf)
	if err != nil {
		return nil, err
	}

	err = rd.Close()
	if err != nil {
		return nil, err
	}

	buf, err = r.decryptTo(buf, ciphertextBuf)
	if err != nil {
		return nil, err
	}

	if !backend.Hash(buf).Equal(id) {
		return nil, errors.New("invalid data returned")
	}

	return buf, nil
}
</context>

