const BaseModel = require('lib/BaseModel');
const { _ } = require('lib/locale.js');
const { bridge } = require('electron').remote.require('./bridge');
const Menu = bridge().Menu;
const MenuItem = bridge().MenuItem;

class NoteListUtils {
	static makeContextMenu(noteIds, props) {
		const notes = noteIds.map(id => BaseModel.byId(props.notes, id));

		let hasEncrypted = false;
		for (let i = 0; i < notes.length; i++) {
			if (notes[i].encryption_applied) hasEncrypted = true;
		}

		const menu = new Menu();

		if (!hasEncrypted) {
			if (props.watchedNoteFiles.indexOf(noteIds[0]) < 0) {
				menu.append(
					new MenuItem({
						label: _('Edit in external editor'),
						enabled: noteIds.length === 1,
						click: async () => {
							props.dispatch({
								type: 'WINDOW_COMMAND',
								name: 'commandStartExternalEditing',
							});
						},
					})
				);
			} else {
				menu.append(
					new MenuItem({
						label: _('Stop external editing'),
						enabled: noteIds.length === 1,
						click: async () => {
							props.dispatch({
								type: 'WINDOW_COMMAND',
								name: 'commandStopExternalEditing',
							});
						},
					})
				);
			}
		}

		return menu;
	}
}
</context>

